"use strict";(self["webpackChunkvue_antd_pro"]=self["webpackChunkvue_antd_pro"]||[]).push([[2728],{3682:function(i){i.exports=JSON.parse('{"info.ReportGuide.header":"欢迎来到“碳排放量填报指南”页面，这里为您提供了一整套详尽的填报步骤和实用技巧，助您轻松完成碳排放量填报任务。遵循本指南，让我们共同为绿色发展、低碳未来努力。","info.ReportGuide.question.qT":"问题","info.ReportGuide.question.1.a":"子公司通常是独立的法人单位或独立的核算单位，需要单独作为报告主体参加碳排放报告核查工作。集团公司需要留存转供凭证，计算各自企业法人边界内的燃料及原材料消耗的活动数据。","info.ReportGuide.question.1.q":"集团公司与子公司在同一个工业园区内，如何处理？","info.ReportGuide.question.2.a":"应根据企业生产运营的实际情况确定碳排放核算范围，包括所有产生温室气体排放的设施和活动。范围确定后，需在数据质量控制计划中明确，并在排放报告中详细说明。","info.ReportGuide.question.2.q":"企业碳排放核算范围应如何确定？","info.ReportGuide.question.3.a":"排放因子是指将某一活动水平数据转换为碳排放量的系数。例如，化石燃料消耗的排放因子是将化石燃料消耗量转换为二氧化碳排放量的系数。排放因子数据主要来源于国家和行业公布的缺省值。如果企业具备条件，也可自行检测获得。在缺乏实测值的情况下，应使用公布的缺省值。","info.ReportGuide.question.3.q":"碳排放核算中的排放因子是什么？如何获取","info.ReportGuide.question.4.a":"活动水平是指企业在一定时间内通过某一排放源产生的温室气体排放量。例如，化石燃料燃烧活动水平是指企业通过燃烧化石燃料产生的二氧化碳排放量。活动水平数据来源于企业对排放源的实际监测。企业需要按照数据质量控制计划的要求，安装和使用监测设备，获取相关排放参数的实测数据。","info.ReportGuide.question.4.q":"碳排放核算中的活动水平是什么？如何获取","info.ReportGuide.question.5.a":"根据不同行业的要求，一般保留到小数点后两位，个别行业可能有更详细的要求。建议在排放报告中明确说明所采用的小数位数。本系统提供至多四位小数保留","info.ReportGuide.question.5.q":"碳排放核算的结果应保留几位小数？","info.ReportGuide.question.6.a":"第三方机构对企业碳排放核算进行核查时，主要核查企业排放边界的合理性、数据质量控制计划执行情况、活动因子和排放因子选择的合理性、监测设备准确性、数据处理方法的规范性，以及核算结果的可靠性等。","info.ReportGuide.question.6.q":"第三方机构如何对企业碳排放核算进行核查？","info.ReportGuide.question.title":"常见问题","info.ReportGuide.shu-ju-jia-gou":"填报数据架构","info.ReportGuide.shu-ju-jia-gou.info":"点击 + 可以展开树状图，查看报送数据详细架构","info.ReportGuide.workflow.title":"填报流程","info.infoSubmission.detailstep.No1.title":"基本信息","info.infoSubmission.detailstep.No2.title":"数据列表","info.infoSubmission.detailstep.No3.title":"报告下载","info.infoSubmission.detailstep.No4":"碳流分布","info.infoSubmission.detailstep.header":"填报数据查询","info.infoSubmission.footer.errorList.field.checkComfirm":"填报任务确认框","info.infoSubmission.footer.errorList.field.fileListsTmp_report":"核算报告文件上传框","info.infoSubmission.footer.errorList.field.fileListsTmp_source":"数据来源文件上传框","info.infoSubmission.footer.errorList.title":"表单校验信息","info.infoSubmission.step.No1.describe":"核对企业基本信息、填报年度等","info.infoSubmission.step.No1.title":"基本信息核对","info.infoSubmission.step.No2.describe":"上报碳排放的一系列相关数据","info.infoSubmission.step.No2.title":"排放数据报送","info.infoSubmission.step.No3.describe":"上传排放数据来源信息，如账本等","info.infoSubmission.step.No3.title":"数据来源上传","info.infoSubmission.step.No4.describe":"预览您的碳排放报告，并上传签字扫描件","info.infoSubmission.step.No4.title":"核算报告预览","info.infoSubmission.step.No5.describe":"等待监管人员审核您提交的信息","info.infoSubmission.step.No5.title":"等待监管审核","info.infoSubmission.step.header":"填报流程进度","info.infoSubmission.title":"请按照填报指南要求，准备好相关材料，填写并提交企业碳排放数据。系统将自动进行数据校验，确保报送数据的准确性和完整性。请用户按照要求认真填写，共同助力碳中和！","info.submissionCenter.annualDataSubmit":"年度数据上报","info.submissionCenter.notask":"暂无报送任务","info.submissionCenter.taskBeginTime":"开始时间","info.submissionCenter.taskEndTime":"结束时间","info.submissionCenter.taskHasEnd":"该报送任务已经结束，您未填报。请联系管理员开放权限进行补填报。请您注意及时填报，因忘记填报造成的损失由企业自行承担！","info.submissionCenter.taskLoading":"报送任务加载中","info.submissionCenter.taskNotBegin":"报送任务目前尚未启动，请耐心等待进一步的指令。在此期间，建议您充分利用时间阅读并理解填报指南中的具体要求，做好材料准备。","info.submissionCenter.taskStatus":"当前状态","info.submissionCenter.taskSubmit":"上报任务","info.submissionCenter.taskSubmit.title":"作为我国碳交易市场的重要组成部分，碳数据上报对于推动碳减排工作具有重要意义。本页面提供了一个便捷、高效的碳数据上报平台，让您能够轻松完成碳数据的收集、整理和提交。","info.submissionCenter.updateInfoShouldNotice":"数据上报须知"}')}}]);